cd /work; psql -tc "select count(*) from (select order_id from order_items oi join products p using(product_id) group by 1 having count(distinct category)>1) x"
# force a multi-category completed order with 2 lines of different categories
psql -v ON_ERROR_STOP=1 <<'EOF'
insert into orders select max(order_id)+1,min(customer_id),now(),'COMPLETED',0 from orders;
insert into order_items select (select max(order_item_id) from order_items)+1, (select max(order_id) from orders), p.product_id, 3, p.unit_price from (select product_id,unit_price from products order by category desc limit 1) p;
insert into order_items select (select max(order_item_id) from order_items)+1, (select max(order_id) from orders), p.product_id, 5, p.unit_price from (select product_id,unit_price from products order by category asc limit 1) p;
select oi.order_item_id, p.category, oi.quantity from order_items oi join products p using(product_id) where order_id=(select max(order_id) from orders) order by 1;
EOF
psql -q -v ON_ERROR_STOP=1 -f etl.sql && psql -tc "select * from etl_run_log order by run_id desc limit 1" -c "select * from dash_revenue_by_category where month=to_char(now(),'YYYY-MM') order by 2"
psql -tc "select count(*) from (select order_id from order_items oi join products p using(product_id) group by 1 having count(distinct category)>1) x"

